-- ============================================================================
-- v1404: Seed / sample data — Change Management registers (v1403) for the demo project
-- ============================================================================
-- Owner request 2026-11-09: sample data where it was missing, 10 records for each Change Management register,
-- for SEED334-PRJ-08 (fictional "Northbridge Bank" core banking replacement, the same scenario as the
-- Cutover, Operational Readiness, Testing and Data Migration samples).
-- Dated around today (11 Nov 2026): the strategy is drafted, impacts are assessed for the main groups,
-- the baseline readiness survey is done, champions are appointed and engagement events are running.
-- Adoption Tracking readings are simulated after the April 2027 go-live (owner decision D9), like Hypercare.
-- Records: strategy 1, impacts 10, readiness 10, network 10, communications 10, resistance 10, adoption 10, signoff 10.
-- Vendor-neutral (rule 26), person fields are plain text. display_id is left blank so Admin ID
-- Generation assigns it (rule 16.2). Fixed hex-only ids …-4000-b044- … b04b- (ranges checked free
-- before use). ON CONFLICT (id) DO NOTHING, and nothing is inserted if the project is missing.
-- Calculated values are worked out with the same rules as the app. The final query counts the
-- records per register, so a skipped insert is visible.
-- Prerequisites: v1403. Idempotent.
-- ============================================================================

INSERT INTO public.local_register_records
  (id, register_id, display_id, title, description, status, field_values, account_id, project_id, record_project_id)
SELECT v.id::uuid, v.register_id::uuid, '', v.title, v.description, v.status, v.vals::jsonb, p.account_id, p.id, p.id
FROM (VALUES
  ('00000000-0000-4000-b044-000000000001', '00000000-0000-4000-9001-000000000044', 'Change Management Strategy – Core Banking Replacement (Release 1)', 'How Northbridge Bank prepares its people for the new core banking platform, and how it knows the change has stuck.', 'draft', $j${"document_reference":"CM-STR-001","document_version":"0.8","document_owner":"Joy Akinyi","next_review_date":"2027-01-29","change_lead":"Joy Akinyi","sponsor":"Grace Moyo","change_scale":"transformational","purpose":"To make sure every affected employee knows what is changing, why, and what it means for them, is ready and able to work the new way at go-live, and keeps working that way afterwards.","objectives":"Every affected employee hears about the change from their own manager first\nReadiness score of 75% or more in every business unit before go-live\nChampion in every branch and operations team\nAdoption targets met within 90 days of go-live","scope":"All staff affected by Release 1: branches, contact centre, operations, finance, risk and IT\nChanges to roles, processes, controls and day-to-day tools\nChange network, engagement, readiness and adoption","out_of_scope":"Release 2 products\nOrganisation restructuring not caused by the new platform","assumptions":"Line managers release staff for briefings and training\nThe staff forum is consulted on role changes","constraints":"No large events during month-end weeks\nBranch staff can only attend sessions outside opening hours on two days a week","change_vision":"One modern banking platform that lets our people serve customers faster, with fewer manual steps and fewer handovers.","case_for_change":"The legacy core is out of support, needs heavy manual work for every new product and cannot support real-time payments. Customers expect instant service, and the regulator expects stronger controls.","what_changes":"Account opening\tPaper forms and overnight approval\tSame-day opening with on-screen approval\nTeller overrides\tPaper override slips\tOn-screen overrides in a work queue\nPayments\tBatch release three times a day\tReal-time release with exception queues\nReporting\tManual spreadsheets\tStandard reports from the reporting store","what_stays":"Customer account numbers stay the same for customers\nBranch opening hours\nWho approves high-value payments","change_approach":"Manager-led change supported by a champion in every team. Awareness first, then preparation through impact briefings and training, go-live support from floor walkers and champions, and reinforcement through adoption measures and recognition.","change_phases":"Awareness\tOct–Dec 2026\tWhy we are changing and what it means\nPreparation\tJan–Mar 2027\tImpact briefings, training, practice\nGo-live\tApr 2027\tFloor walkers, champions, fast answers\nReinforcement\tMay–Jul 2027\tAdoption measures, coaching, recognition","impacted_groups":"Tellers and customer service\t1,180\tHigh\nPayments operations\t90\tHigh\nContact centre agents\t180\tHigh\nFinance\t55\tMedium\nRelationship managers\t140\tMedium\nRisk and compliance\t45\tLow","governance":"The change lead reports to the programme board monthly. A change working group of business-unit change leads meets weekly. Readiness results feed the go / no-go decisions.","roles_and_responsibilities":"Executive sponsor\tVisible leadership, removes blockers\tGrace Moyo\nChange management lead\tRuns the change plan and readiness measures\tJoy Akinyi\nBusiness-unit change leads\tOwn readiness in their unit\tUnit heads\nChange champions\tLocal voice and support in each team\tNamed in the Change Network register","network_model":"One champion for every 25–30 staff, at least one in every branch. Champions are volunteers nominated by their manager and briefed every two weeks.","champion_ratio":"1 : 25","champion_commitment":"About 2 hours a week, rising to full time in go-live week","engagement_principles":"Managers tell their teams first\nExplain what changes for each role, not just the system\nListen and act on feedback within two weeks","key_messages":"We are changing to serve customers faster and more safely\nYou will be trained and supported before and after go-live\nYour champion is your first port of call","engagement_calendar":"Oct 2026\tLeadership launch and town hall\tAll staff\tGrace Moyo\nNov 2026\tRegional roadshows\tBranch staff\tJoy Akinyi\nJan 2027\tImpact briefings by manager\tEach team\tLine managers\nMar 2027\tGo-live readiness huddles\tAll staff\tChampions","readiness_measures":"Readiness score by business unit\t75% or more\tBaseline, February, before go-live\nStaff who know their champion\t90% or more\tPulse checks","adoption_measures":"Transactions done in the new process\t95% or more\tSystem reports\nUse of paper workarounds\tBelow 2%\tBranch spot checks\nStaff confidence with the new system\t4 out of 5\tPost-go-live survey","sustainment":"Adoption reviewed monthly for 3 months after go-live\nChampions continue as super users\nProcess owners take over adoption measures","risks_mitigations":"Change fatigue alongside other initiatives\tLow engagement\tAlign timing with HR and operations calendars\tJoy Akinyi\nManagers not briefing teams\tInconsistent messages\tManager toolkit and briefing tracking\tUnit heads","glossary":"Change champion\tA volunteer in a team who supports colleagues through the change.\nReadiness score\tAverage of five readiness dimensions, as a percentage.","appendices":"Change Impact Assessment\tChange Impact Assessment register\nChange Network\tChange Network register","version_history":"0.1\t2026-08-20\tJoy Akinyi\tFirst draft\n0.8\t2026-11-06\tJoy Akinyi\tBaseline readiness results added","related_documents":"Training Strategy\tTR-STR-001\nCutover Strategy\tCUT-STR-001\nHypercare Plan\tHC-PLN-001"}$j$),
