-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9001-000000000044'::uuid, '00000000-0000-4000-9001-000000000045'::uuid, '00000000-0000-4000-9001-000000000046'::uuid, '00000000-0000-4000-9001-000000000047'::uuid, '00000000-0000-4000-9001-000000000048'::uuid, '00000000-0000-4000-9001-000000000049'::uuid, '00000000-0000-4000-9001-00000000004a'::uuid, '00000000-0000-4000-9001-00000000004b'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
